    await expect(page.locator("#description")).toHaveAttribute("maxlength", "30");

    await fillVisitDate(page, "2026/08/29");
    await fillVisitDescription(page, "1234567890123456789012345678901");
    await expect(page.getByRole("textbox", { name: "Description" })).toHaveValue("123456789012345678901234567890");
    await expect(page.getByRole("button", { name: "Add Visit" })).toBeEnabled();

    await fillVisitDescription(page, "");
    await expect(page.getByText("Description is required")).toBeVisible();
    await expect(page.getByRole("button", { name: "Add Visit" })).toBeDisabled();
